    "script": "(8) タクシーを呼ぶ相談をしています。タクシーは何台呼びますか。\n男：楽しいパーティーだったねえ。\n女：そうねえ。\n女：ほんと。\n男：電話でタクシーを呼ぼうか。\n女：そうねえ。\n男：ええと、9人だから、タクシーは。\n女：2台じゃ、無理よねえ。\n男：そうだね。一台に5人は乗れないもんねえ。ええと、みんな駅まででしょう。\n女：あのう、私と主人は反対の方なんですけど。\n男：じゃ、もう1台か。\n女：でも、お2人が1台に乗って、あと7人だから、4人と3人でいいんじゃない。\n男：ああ、そうだね。そうしよう。\nタクシーは何台呼びますか。",
    "imageDescription": "タクシーの台数を示す4パターンの絵（①2台 ②3台 ③4台 ④5台）。",
    "imageUrl": "/exam-images/jlpt-n3-2000/lis-I-8.png",
