    "script": "(10) 子どもがお母さんに買い物を頼みました。お母さんはどれを買いますか。\n子：お母さん、買い物に行くの？本、買ってきてくれる？\n母：何？\n子：『ゆめ』っていうの。\n母：『ゆめ』ね。\n子：あ、『ゆめ』の３だよ。１と２はもう読んだから。\nお母さんはどれを買いますか。",
