      "「けいかん」是警察，工作內容跟「照顧病人」無關，錯誤。",
      "「えきいん」是車站站務員，工作內容跟「照顧病人」無關，錯誤。",
      "「かんごふ」是護士，負責照顧病人、隨時應對突發狀況，符合原文描述，為正解。"
