    "script": "男の人と女の人が店で話しています。男の人は全部でいくら出しましたか。\n－はい、2200円。－あのう、すみません。もう100円です。－あ、すみません。じゃ、これ、100円。－はい、ありがとうございました。\n男の人は全部でいくら出しましたか。",
