    "script": "男の人と女の人が話しています。二人が見ている皿はどれですか。\n男：あれ、これ大丈夫？\n女：え、どうして？\n男：ほら、ここ、割れそうだよ。\n女：あ、本当だ。ちょっとだけどね。\n二人が見ている皿はどれですか。",
    "imageDescription": "皿のイラスト4パターン（画像には「7ばん」と明記されている）。無傷の丸皿、ひびが入った丸皿、割れかけの丸皿、花びら型の皿など形状が異なる（正解はひびが少し入っている丸皿）。",
