    "script": "男の人と女の人が話しています。部屋はどうなりましたか。\n女：きのう、たいへんだったのよ。\n男：どうしたの？\n女：ねこがね、テレビの上にあがって人形（にんぎょう）を落（お）として。\n男：そう。\n女：それで、ねこが下にとびおりて。\n男：え、それで？\n女：そしたら下にあったジュースがたおれて、大事（だいじ）な人形がよごれてしまったのよ。\n男：あ、そうなの。\n部屋はどうなりましたか。",
