    "script": "男の人と女の人が話しています。女の人はいつ写真を取りに行きますか。\n女：あの、これいつできますか。ちょっと急（いそ）いでいるんですけど。\n男：３日かかります。今日が４日ですから、５、６、７、あ、すみません。７日は水曜日ですね。水曜日は店が休みなので、８日になりますが。\n女：８日ですか…\n男：じゃ、休みの前にやっておきましょう。休みの前の日の５時すぎに来てください。\n女：はい、そうします。よろしく。\n女の人はいつ写真を取りに行きますか。",
