    "script": "女の人が話しています。学生の数（かず）のグラフはどれですか。\n女：えー、これはある大学の学生の数です。男の学生は１９７０年まで増えてきましたが、そこから急に少なくなりはじめました。女の学生は、はじめは男性（だんせい）より少なかったんですが、少しずつ増えました。１９８５年にはもう女性（じょせい）のほうが男性より多かったです。\n学生の数のグラフはどれですか。",
