    "script": "男の人と女の人が話しています。男の人がするスポーツはどれですか。\n女：高橋さんはどのスポーツをするんですか。　男：なんだと思いますか。　女：サッカーとか野球とか？　男：いいえ、大勢でするスポーツはだめなんですよ。　女：じゃあ、泳いだり、走ったり？　男：いいえ、一人だけのちょっと寂しくて。　女：あー。\nそれじゃー男の人がするスポーツはどれですか。",
    "imageDescription": "4種類のスポーツのイラスト（①テニス ②ランニング ③サッカー ④水泳）。",
