    "script": "お父さんとお母さんが話しています。この人たちの子供が描いた絵はどれですか。\nお父さん：この絵、何？　お母さん：あ、それ？タクシーで描いたお父さんの顔。　お父さん：え、僕？どうして髪が一本だけなんだろう？僕は髪が多いのに。　お母さん：一本もないよりいいでしょう。　お父さん：この、真ん中に描いてある長い横の線は何？　お母さん：あ、それは鬚よ。　お父さん：あ？鬚か？鼻を描いてないから分からないんだよ。\nこの人たちの子供が描いた絵はどれですか。",
