      "sourceNote": "轉自 2003年日本語能力試験3級 真題PDF（聴解／文字語彙／読解文法 三份分卷PDF）。答案來源：2003能力考3级答案.pdf（單頁掃描表格，600dpi視覺讀取），但該掃描頁僅收錄文字語彙（問題I〜V，共55題）與聴解問題I（1ばん〜13ばん）的正解，並無聴解問題II、読解文法部分的答案（掃描件背面墨跡透印可見另一頁答案表的輪廓，但字跡過淡且鏡像反轉，無法可靠辨識，未採用）。読解文法（問題I〜VI）之答案為逐題以日文語感重新推導，未能與任何官方答案來源交叉核對，多數為無歧義的基礎文法/語彙題，信心度高；問題V的②③兩小題（拜託打工排班的敬語表現）語意/語用判斷較複雑、無法排除另一選項亦通的可能性，故標記needsReview。聴解問題II（13題）原始PDF本身完全未印出對話原文或選項文字（僅顯示題號與「絵などがありません」字樣），本年份資料夾內也沒有.doc補充聽力原文檔案，故全部13題標記needsReview，script/options留null。文字語彙問題I第5問(3)小題「鳥」的四個選項在原始PDF中完全空白（僅印出「１．２．３．４．」無任何假名文字），問題II第1問(3)小題「みじかい」選項1與2印刷成完全相同的文字「短い」、第3問(1)小題「かぞく」選項1與3同為「家旅」、選項2與4同為「家族」（兩兩重複）、第4問(3)小題「あかく」選項1與4缺字、第5問(2)小題「おなじ」選項2與3缺字，以上共5小題皆為原始印刷缺陷，標記needsReview並排除於題庫外，來源JSON中保留原始題幹供未來人工核對。",
