      "sourceNote": "轉自 2004年日本語能力試験3級 真題PDF（聴解／文字語彙／読解文法 三份分卷PDF）。答案來源：2004能力考3级答案.pdf（單頁掃描表格，1200dpi視覺讀取，分區裁切核對），本年份的掃描答案頁罕見地完整收錄全部三節的官方正解（文字語彙問題I〜V共55題、聴解問題I 1〜14ばん、聴解問題II 1〜11ばん、読解文法問題I〜VI共50題——読解文法的正解另外還有一份「读解文法.jpg」單頁清晰掃描可交叉核對，兩份來源完全一致），是目前已處理的四個年份（2000、2001、2002、2003）中唯一答案覆蓋率100%的一年。文字語彙、読解文法部分之官方答案已逐題以日文語感重新推導交叉驗證，全部吻合，信心度高。聴解問題Iの14題原始PDF本身（如同真實JLPT聴解考卷的慣例）僅印出插圖與選項編號、並未印出對話原文，本年份資料夾內也沒有.doc補充聽力原文檔案，且執行環境無法直接處理.mp3音檔進行逐字聽寫，故這14題的script欄位留null（僅靠imageDescription描述插圖內容），answerIndex取自官方答案卡但無法如同其他文字/文法題目一樣以日文語感逐句交叉驗證——這點與文字語彙/読解文法題目的驗證信心度不同，請人工留意。聴解問題II（11題）原始PDF該部分僅印出「絵などがありません」與空白的題號/選項編號、完全未印出對話原文或文字選項，本年份資料夾內亦無.doc補充聽力原文檔案可供補完，故全部11題標記needsReview，script/options留null，未擅自編造對話或選項。文字語彙問題II第2問(1)小題「しんせつ」選項2與選項4皆印刷成完全相同的文字「新扐」，屬原始印刷缺陷（雖不影響本題可作答性，正解為選項3「親切」，但兩個干擾選項重複印刷仍視為缺陷），標記needsReview並排除於題庫外。読解文法問題I第7問「ここをおす＿＿＿、にんぎょうが動きます。」選項4在原始PDF中完全空白（僅印出「４．」而無任何假名文字），屬原始印刷缺陷，標記needsReview並排除於題庫外（正解為選項3「と」，本身不受影響，但選項4缺字仍視為缺陷）。読解文法問題VI（最後一篇「アンさんへの手紙」）的読解文法.pdf原始文字層漏印了倒數第二段（「私は四月に高校生になりました…高校でもバスケットボールをつづけています。新しい友達がたくさんできました。」），資料夾內另附「最后一篇阅读卷子有漏倒数第二段.jpg」提供該段落的完整原文照片，本次已將該段落插回文章正確位置（第2段），並據此正確推導出問49「正しいものはどれですか」的答案（選項2「高校へ行くのに時間がかかります」，因為修復後的段落提到「一時間もかかる」），與官方答案卡的「2」完全吻合，可視為復原成功的驗證。",
