    "script": "1 番 学生が先生に漢字のテストについて聞いています。学生が書いた漢字はどれですか。学生：先生、先週の漢字のテストですけど、これですね。 先生：これですね。 学生：はい。いぬっていう漢字を書いたんですが、どこがまちがっているんでしょう。 先生：点はここで正しいですか。 学生：あのう、点は横の線の下じゃなくて、上につけましたが、あっ、ひだりにつけてしまいました。",
