    "script": "7 番 男の人と女の人が昨日の散歩について話しています。女の人の話について正しい絵はどれですか。女の人：昨日、山へ行ったの、とても楽しかった。 男の人：よかったね、お天気もよかったし。 女の人：いいえ、山は雨だったの。でも、私の犬は雨が好きだから、いっしょに散歩したの。男の人：友達も一緒？ 女の人：うーん、友達は行かなかった。 男の人：あっ、そう。",
    "imageDescription": "雨の中を犬と散歩する人物のイラスト4パターン。①傘をさす男女2人＋犬（雨） ②傘をさす女性1人＋犬（雨） ③男女2人＋犬（晴れ） ④女性1人＋犬（晴れ）。",
