    "script": "10 番 医者と男の人が話しています。体によくないやり方はどれですか。よくないやり方です。男の人：先生、ちょっと聞きたいですけど。泳いだり、走ったり、テニスをしたり、一日続けてやってもいいですか。 女の人：そうですね、走ったり、テニスをしたりしてから、泳ぐのは危ないですよ。男の人：あっ、そうですか、水泳をしてから、ほかの運動をするのは 女の人：それなら、いいですよ。とにかく、たくさん運動をした後で、水泳をするのはやめたほうがいいです。",
    "imageDescription": "運動の順番を示す4パターンのイラスト（矢印は「その後に行う」の意味）。①走る→泳ぐ ②泳ぐ→走る ③泳ぐ→テニス ④テニス→走る。",
