    "script": "11 番 学校で、男の人と女の人が話しています。二人はいつ映画を見に行きますか。男の人：あした、映画にいかない？毎月一日は安いんだよ。 女の人：明日はちょっと、再来週の月曜日に大切なテストがあるんで。 男の人：再来週なら、まだいいんじゃない？女の人：でも 男の人：テストの後の週末、土曜日ならいい？ 女の人：いいけど、安くないでしょう。 男の人：大丈夫。僕が払うから、行こう。女の人：ほんとう、じゃ。",
