    "script": "12 番 お母さんと娘がデパートで話しています。二人は今何を見ていますか。娘：ねえ、父の日のプレゼント、これ、どう？ 母：お父さんは、こんな色のは、しないと思うよ。 娘：でも、茶色の背広をよく着るでしょう？白いの上にこれを締めて、その上に茶色の背広を着ると、いいと思うよ。 母：そうね、いいかもしれないわね。",
