    "script": "女の人と男の人が会社で話しています。男の人の子どもはどの子ですか。\n女：わあ、かわいい。見せて、見せて。\n男：娘の誕生日パーティーの写真なんだ。\n女：へえ、で、田中さんのお子さんはこの一番右の子でしたっけ。\n男：ううん。ほら、その帽子をかぶって、椅子に座っているのがそうだよ。\n男の人の子どもはどの子ですか。",
    "imageDescription": "4人の女の子が並んだイラスト（①②③④）。①は三角帽をかぶり立っている、②は帽子なしで椅子に座っている、③は三角帽をかぶり椅子に座ってピースしている、④は帽子なしで立っている。正解は「帽子をかぶって椅子に座っている」③。",
